CREATE DATABASE IF NOT EXISTS `wordpress`;
USE `wordpress`;

CREATE TABLE `wp_actionscheduler_actions` (
  `action_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `args` VARCHAR(191),
  `attempts` INT NOT NULL DEFAULT '0',
  `claim_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `extended_args` VARCHAR(8000),
  `group_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `hook` VARCHAR(191) NOT NULL,
  `last_attempt_gmt` DATETIME DEFAULT NULL,
  `last_attempt_local` DATETIME DEFAULT NULL,
  `priority` TINYINT UNSIGNED NOT NULL DEFAULT '10',
  `schedule` LONGTEXT,
  `scheduled_date_gmt` DATETIME DEFAULT NULL,
  `scheduled_date_local` DATETIME DEFAULT NULL,
  `status` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`action_id`)
);

CREATE TABLE `wp_actionscheduler_claims` (
  `claim_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `date_created_gmt` DATETIME DEFAULT NULL,
  PRIMARY KEY (`claim_id`)
);

CREATE TABLE `wp_actionscheduler_groups` (
  `group_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`group_id`)
);

CREATE TABLE `wp_actionscheduler_logs` (
  `action_id` BIGINT UNSIGNED NOT NULL,
  `log_date_gmt` DATETIME DEFAULT NULL,
  `log_date_local` DATETIME DEFAULT NULL,
  `log_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `message` TEXT NOT NULL,
  PRIMARY KEY (`log_id`)
);

CREATE TABLE `wp_commentmeta` (
  `comment_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `meta_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `meta_key` VARCHAR(255),
  `meta_value` LONGTEXT,
  PRIMARY KEY (`meta_id`)
);

CREATE TABLE `wp_comments` (
  `comment_agent` VARCHAR(255) NOT NULL DEFAULT '',
  `comment_approved` VARCHAR(20) NOT NULL DEFAULT '1',
  `comment_author` TINYTEXT NOT NULL,
  `comment_author_email` VARCHAR(100) NOT NULL DEFAULT '',
  `comment_author_IP` VARCHAR(100) NOT NULL DEFAULT '',
  `comment_author_url` VARCHAR(200) NOT NULL DEFAULT '',
  `comment_content` TEXT NOT NULL,
  `comment_date` DATETIME NOT NULL,
  `comment_date_gmt` DATETIME NOT NULL,
  `comment_ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `comment_karma` INT NOT NULL DEFAULT '0',
  `comment_parent` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `comment_post_ID` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `comment_type` VARCHAR(20) NOT NULL DEFAULT 'comment',
  `user_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`comment_ID`)
);

CREATE TABLE `wp_links` (
  `link_description` VARCHAR(255) NOT NULL DEFAULT '',
  `link_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `link_image` VARCHAR(255) NOT NULL DEFAULT '',
  `link_name` VARCHAR(255) NOT NULL DEFAULT '',
  `link_notes` MEDIUMTEXT NOT NULL,
  `link_owner` BIGINT UNSIGNED NOT NULL DEFAULT '1',
  `link_rating` INT NOT NULL DEFAULT '0',
  `link_rel` VARCHAR(255) NOT NULL DEFAULT '',
  `link_rss` VARCHAR(255) NOT NULL DEFAULT '',
  `link_target` VARCHAR(25) NOT NULL DEFAULT '',
  `link_updated` DATETIME NOT NULL,
  `link_url` VARCHAR(255) NOT NULL DEFAULT '',
  `link_visible` VARCHAR(20) NOT NULL DEFAULT 'Y',
  PRIMARY KEY (`link_id`)
);

CREATE TABLE `wp_options` (
  `autoload` VARCHAR(20) NOT NULL DEFAULT 'yes',
  `option_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `option_name` VARCHAR(191) NOT NULL DEFAULT '',
  `option_value` LONGTEXT NOT NULL,
  PRIMARY KEY (`option_id`)
);

CREATE TABLE `wp_postmeta` (
  `meta_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `meta_key` VARCHAR(255),
  `meta_value` LONGTEXT,
  `post_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`meta_id`)
);

CREATE TABLE `wp_posts` (
  `comment_count` BIGINT NOT NULL DEFAULT '0',
  `comment_status` VARCHAR(20) NOT NULL DEFAULT 'open',
  `guid` VARCHAR(255) NOT NULL DEFAULT '',
  `ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `menu_order` INT NOT NULL DEFAULT '0',
  `ping_status` VARCHAR(20) NOT NULL DEFAULT 'open',
  `pinged` TEXT NOT NULL,
  `post_author` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `post_content` LONGTEXT NOT NULL,
  `post_content_filtered` LONGTEXT NOT NULL,
  `post_date` DATETIME NOT NULL,
  `post_date_gmt` DATETIME NOT NULL,
  `post_excerpt` TEXT NOT NULL,
  `post_mime_type` VARCHAR(100) NOT NULL DEFAULT '',
  `post_modified` DATETIME NOT NULL,
  `post_modified_gmt` DATETIME NOT NULL,
  `post_name` VARCHAR(200) NOT NULL DEFAULT '',
  `post_parent` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `post_password` VARCHAR(255) NOT NULL DEFAULT '',
  `post_status` VARCHAR(20) NOT NULL DEFAULT 'publish',
  `post_title` TEXT NOT NULL,
  `post_type` VARCHAR(20) NOT NULL DEFAULT 'post',
  `to_ping` TEXT NOT NULL,
  PRIMARY KEY (`ID`)
);

CREATE TABLE `wp_term_relationships` (
  `object_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `term_order` INT NOT NULL DEFAULT '0',
  `term_taxonomy_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`object_id`, `term_taxonomy_id`)
);

CREATE TABLE `wp_term_taxonomy` (
  `count` BIGINT NOT NULL DEFAULT '0',
  `description` LONGTEXT NOT NULL,
  `parent` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `taxonomy` VARCHAR(32) NOT NULL DEFAULT '',
  `term_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `term_taxonomy_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  PRIMARY KEY (`term_taxonomy_id`)
);

CREATE TABLE `wp_termmeta` (
  `meta_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `meta_key` VARCHAR(255),
  `meta_value` LONGTEXT,
  `term_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`meta_id`)
);

CREATE TABLE `wp_terms` (
  `name` VARCHAR(200) NOT NULL DEFAULT '',
  `slug` VARCHAR(200) NOT NULL DEFAULT '',
  `term_group` BIGINT NOT NULL DEFAULT '0',
  `term_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  PRIMARY KEY (`term_id`)
);

CREATE TABLE `wp_usermeta` (
  `meta_key` VARCHAR(255),
  `meta_value` LONGTEXT,
  `umeta_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`umeta_id`)
);

CREATE TABLE `wp_users` (
  `display_name` VARCHAR(250) NOT NULL DEFAULT '',
  `ID` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `user_activation_key` VARCHAR(255) NOT NULL DEFAULT '',
  `user_email` VARCHAR(100) NOT NULL DEFAULT '',
