  `first_name` VARCHAR(255) NOT NULL,
  `last_name` VARCHAR(255) NOT NULL,
  `postcode` VARCHAR(20) NOT NULL DEFAULT '',
  `state` VARCHAR(100) NOT NULL DEFAULT '',
  `user_id` BIGINT UNSIGNED,
  `username` VARCHAR(60) NOT NULL DEFAULT '',
