  `consumer_key` CHAR(64) NOT NULL,
  `consumer_secret` CHAR(43) NOT NULL,
  `description` VARCHAR(200),
  `key_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `last_access` DATETIME,
  `nonces` LONGTEXT,
  `permissions` VARCHAR(10) NOT NULL,
  `truncated_key` CHAR(7) NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`key_id`)
);

CREATE TABLE `wp_woocommerce_attribute_taxonomies` (
  `attribute_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `attribute_label` VARCHAR(200),
  `attribute_name` VARCHAR(200) NOT NULL,
  `attribute_orderby` VARCHAR(20) NOT NULL,
  `attribute_public` INT NOT NULL DEFAULT '1',
  `attribute_type` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`attribute_id`)
);

CREATE TABLE `wp_woocommerce_downloadable_product_permissions` (
  `access_expires` DATETIME,
  `access_granted` DATETIME NOT NULL,
  `download_count` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `download_id` VARCHAR(36) NOT NULL,
  `downloads_remaining` VARCHAR(9),
  `order_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  `order_key` VARCHAR(200) NOT NULL,
  `permission_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `user_email` VARCHAR(200) NOT NULL,
  `user_id` BIGINT UNSIGNED,
  PRIMARY KEY (`permission_id`)
);

CREATE TABLE `wp_woocommerce_log` (
  `context` LONGTEXT,
  `level` SMALLINT NOT NULL,
  `log_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `message` LONGTEXT NOT NULL,
  `source` VARCHAR(200) NOT NULL,
  `timestamp` DATETIME NOT NULL,
  PRIMARY KEY (`log_id`)
);

CREATE TABLE `wp_woocommerce_order_itemmeta` (
  `meta_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `meta_key` VARCHAR(255),
  `meta_value` LONGTEXT,
  `order_item_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`meta_id`)
);

CREATE TABLE `wp_woocommerce_order_items` (
  `order_id` BIGINT UNSIGNED NOT NULL,
  `order_item_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `order_item_name` TEXT NOT NULL,
  `order_item_type` VARCHAR(200) NOT NULL DEFAULT '',
  PRIMARY KEY (`order_item_id`)
);

CREATE TABLE `wp_woocommerce_payment_tokenmeta` (
  `meta_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `meta_key` VARCHAR(255),
  `meta_value` LONGTEXT,
  `payment_token_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`meta_id`)
);

CREATE TABLE `wp_woocommerce_payment_tokens` (
  `gateway_id` VARCHAR(200) NOT NULL,
  `is_default` TINYINT(1) NOT NULL DEFAULT '0',
  `token` TEXT NOT NULL,
  `token_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `type` VARCHAR(200) NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL DEFAULT '0',
  PRIMARY KEY (`token_id`)
);

CREATE TABLE `wp_woocommerce_sessions` (
  `session_expiry` BIGINT UNSIGNED NOT NULL,
  `session_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `session_key` CHAR(32) NOT NULL,
  `session_value` LONGTEXT NOT NULL,
  PRIMARY KEY (`session_id`)
);

CREATE TABLE `wp_woocommerce_shipping_zone_locations` (
  `location_code` VARCHAR(200) NOT NULL,
  `location_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `location_type` VARCHAR(40) NOT NULL,
  `zone_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`location_id`)
);

CREATE TABLE `wp_woocommerce_shipping_zone_methods` (
  `instance_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `is_enabled` TINYINT(1) NOT NULL DEFAULT '1',
  `method_id` VARCHAR(200) NOT NULL,
  `method_order` BIGINT UNSIGNED NOT NULL,
  `zone_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`instance_id`)
);

CREATE TABLE `wp_woocommerce_shipping_zones` (
  `zone_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `zone_name` VARCHAR(200) NOT NULL,
  `zone_order` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`zone_id`)
);

CREATE TABLE `wp_woocommerce_tax_rate_locations` (
  `location_code` VARCHAR(200) NOT NULL,
  `location_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `location_type` VARCHAR(40) NOT NULL,
  `tax_rate_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`location_id`)
);

CREATE TABLE `wp_woocommerce_tax_rates` (
  `tax_rate` VARCHAR(8) NOT NULL DEFAULT '',
  `tax_rate_class` VARCHAR(200) NOT NULL DEFAULT '',
  `tax_rate_compound` INT NOT NULL DEFAULT '0',
  `tax_rate_country` VARCHAR(2) NOT NULL DEFAULT '',
  `tax_rate_id` BIGINT UNSIGNED AUTO_INCREMENT NOT NULL,
  `tax_rate_name` VARCHAR(200) NOT NULL DEFAULT '',
  `tax_rate_order` BIGINT UNSIGNED NOT NULL,
  `tax_rate_priority` BIGINT UNSIGNED NOT NULL,
  `tax_rate_shipping` INT NOT NULL DEFAULT '1',
  `tax_rate_state` VARCHAR(200) NOT NULL DEFAULT '',
  PRIMARY KEY (`tax_rate_id`)
);

